import sys
from functools import lru_cache

def solve(n, m, arrivals, times):
    start_state = tuple([0] * m)

    @lru_cache(maxsize=None)
    def dfs(free_times, remaining):
        if not remaining:
            return 0
        best = 10**18
        for i in remaining:
            for b in range(m):
                start = max(free_times[b], arrivals[i])
                finish = start + times[i]
                wait = finish - arrivals[i]
                new_free = list(free_times)
                new_free[b] = finish
                new_remaining = tuple(x for x in remaining if x != i)
                best = min(best, wait + dfs(tuple(new_free), new_remaining))
        return best

    return dfs(start_state, tuple(range(n)))

def main():
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    arrivals = data[2:2 + n]
    times = data[2 + n:2 + 2 * n]
    print(solve(n, m, arrivals, times))

if __name__ == "__main__":
    main()
